const listUnsettledCaptures = `-- name: ListUnsettledCaptures :many
SELECT p.id, p.provider_payment_id, p.amount_captured, t.effective_at AS captured_at
FROM payments p
JOIN ledger_transactions t ON t.id = p.capture_txn_id
WHERE p.provider = $1
  AND t.effective_at < $2
  AND NOT EXISTS (
      SELECT 1 FROM settlement_lines l
      WHERE l.provider = p.provider AND l.entity_type = 'payment'
        AND l.entity_id = p.provider_payment_id AND l.result = 'matched'
  )
ORDER BY t.effective_at
LIMIT 500
`

type ListUnsettledCapturesParams struct {
	Provider    string    `json:"provider"`
	EffectiveAt time.Time `json:"effective_at"`
}

type ListUnsettledCapturesRow struct {
	ID                uuid.UUID `json:"id"`
	ProviderPaymentID *string   `json:"provider_payment_id"`
	AmountCaptured    int64     `json:"amount_captured"`
	CapturedAt        time.Time `json:"captured_at"`
}

// Captured payments with no matched settlement line, captured before a
// cutoff (the processor should have settled them by now).
func (q *Queries) ListUnsettledCaptures(ctx context.Context, arg ListUnsettledCapturesParams) ([]ListUnsettledCapturesRow, error) {
	rows, err := q.db.Query(ctx, listUnsettledCaptures, arg.Provider, arg.EffectiveAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUnsettledCapturesRow
	for rows.Next() {
		var i ListUnsettledCapturesRow
		if err := rows.Scan(
			&i.ID,
			&i.ProviderPaymentID,
			&i.AmountCaptured,
			&i.CapturedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

