const markWebhookFailed = `-- name: MarkWebhookFailed :exec
UPDATE webhook_events
SET last_error = $1,
    next_retry_at = now() + make_interval(secs => $2::float8)
WHERE id = $3
`

type MarkWebhookFailedParams struct {
	LastError      *string  `json:"last_error"`
	RetryInSeconds *float64 `json:"retry_in_seconds"`
	ID             int64    `json:"id"`
}

// Retry times use the database clock, the same one the claim queries
// compare against, so app/DB clock skew cannot delay or hide a retry.
// A NULL delay means "do not retry".
func (q *Queries) MarkWebhookFailed(ctx context.Context, arg MarkWebhookFailedParams) error {
	_, err := q.db.Exec(ctx, markWebhookFailed, arg.LastError, arg.RetryInSeconds, arg.ID)
	return err
}

